def fraksi_teoretis(pa, pb, pc):
    wa = pa
    wb = (1 - pa) * pb
    wc = (1 - pa) * (1 - pb) * pc
    t = wa + wb + wc
    return round(wa / t, 4), round(wb / t, 4), round(wc / t, 4)

